// Write all chunk files (12 chunks: chunk-0 to chunk-11)
const CHUNK_SIZE = 100;
const TOTAL_CHUNKS = Math.ceil(1124 / CHUNK_SIZE);

for (let c = 0; c < TOTAL_CHUNKS; c++) {
  const startIdx = c * CHUNK_SIZE;
  const endIdx = Math.min(startIdx + CHUNK_SIZE, 1124);
  const chunkPages = allPages.slice(startIdx, endIdx);
  const chunkPath = path.join(chunksDir, `chunk-${c}.json`);
  fs.writeFileSync(chunkPath, JSON.stringify(chunkPages, null, 2), 'utf8');
  console.log(`Saved chunk-${c}.json (pages ${startIdx + 1}..${endIdx}, total: ${chunkPages.length})`);
}

// Write meta.json
